import java.util.*;

public class Main {
    static final int WHITE = 0, GREY = 1, BLACK = 2;

    static List<String> mark(Map<String, List<String>> g, List<String> roots) {
        Map<String, Integer> color = new LinkedHashMap<>();
        for (String k : g.keySet()) color.put(k, WHITE);
        Deque<String> grey = new ArrayDeque<>();
        for (String r : roots) { color.put(r, GREY); grey.add(r); }
        int visited = 0;
        while (!grey.isEmpty()) {
            String cur = grey.poll();
            for (String nxt : g.getOrDefault(cur, List.of()))
                if (color.get(nxt) == WHITE) { color.put(nxt, GREY); grey.add(nxt); }
            color.put(cur, BLACK);
            visited++;
            System.out.println("    grey=" + cur + " -> black");
        }
        List<String> white = new ArrayList<>();
        for (Map.Entry<String, Integer> e : color.entrySet())
            if (e.getValue() == WHITE) white.add(e.getKey());
        Collections.sort(white);
        System.out.println("    black(visited) = " + visited);
        return white;
    }

    public static void main(String[] args) {
        // A -> B -> D ; A -> C ;  E <-> F 自成环（引用计数的死穴）
        Map<String, List<String>> g = new LinkedHashMap<>();
        g.put("A", List.of("B", "C"));
        g.put("B", List.of("D"));
        g.put("C", List.of());
        g.put("D", List.of());
        g.put("E", List.of("F"));
        g.put("F", List.of("E"));

        System.out.println("=== reachability analysis, GC Roots = [A] ===");
        List<String> dead = mark(g, List.of("A"));
        System.out.println("    unreachable (white) = " + dead);
        System.out.println("    cyclic pair E,F collected = " + dead.containsAll(List.of("E", "F")));
        System.out.println("    reference counting would keep E and F forever = true");

        System.out.println("=== same graph, add root E ===");
        List<String> dead2 = mark(g, List.of("A", "E"));
        System.out.println("    unreachable (white) = " + dead2);
        System.out.println("    nothing dead now = " + dead2.isEmpty());
    }
}
